package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class GradeRetractionApiTest {
 SubmissionApiTest f;GradeRetractionStore store;GradeRetractionController api;
 @BeforeEach void setup(){f=new SubmissionApiTest();f.setup();store=mock(GradeRetractionStore.class);api=new GradeRetractionController(store,f.f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String content){var r=f.req(method,content);r.removeHeader("If-Match");r.addHeader("If-Match","\"gr0\"");return r;}
 String input(){return "{\"state\":\"RETRACTED\",\"reason\":\"Grade\"}";}
 GradeRetractionStore.Retraction value(){return new GradeRetractionStore.Retraction(f.f.id,f.f.id,1,f.f.id,1,f.assignment,2,f.study,f.f.group,f.f.space,f.f.actor,f.f.actor,1,"RETRACTED","Grade","AUTHOR_AND_OWNER",Instant.now().toString(),Instant.now().toString());}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 Object change(MockHttpServletRequest r)throws Exception{return api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",r);}
 @Test void onlyCurrentOwnerWritesUsingAuthenticatedActorAndIndependentEtag()throws Exception{var v=value();when(store.change(eq(f.f.group),eq(f.f.space),eq(f.study),eq(f.assignment),eq(f.f.id),eq(f.f.actor),eq(1L),eq(0L),eq(new GradeRetractionInput("RETRACTED","Grade")),anyString())).thenReturn(v);var response=api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",req("PUT",input()));assertEquals("\"gr1\"",response.getHeaders().getETag());assertEquals("no-store",response.getHeaders().getCacheControl());verify(store).change(eq(f.f.group),eq(f.f.space),eq(f.study),eq(f.assignment),eq(f.f.id),eq(f.f.actor),eq(1L),eq(0L),any(),anyString());}
 @Test void memberAndViewerCannotWriteGrade(){for(var role:List.of("MEMBER","VIEWER")){f.f.role(role);status(403,()->change(req("PUT",input())));}verifyNoInteractions(store);}
 @Test void nonOwnerReadAndHistoryAreAuthorScopedWithoutWriteOrigin()throws Exception{f.f.role("VIEWER");when(store.get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,false,1)).thenReturn(new GradeRetractionStore.View(f.f.id,1,null,false));var r=req("GET",null);r.removeHeader("Origin");var response=api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",r);assertEquals("\"gr0\"",response.getHeaders().getETag());api.history(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",req("GET",null));verify(store).get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,false,1);verify(store).history(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,false,1,Long.MAX_VALUE,5);}
 @Test void ownerReadUsesExistingOwnerVisibilityWithoutGrantingActorSelectors()throws Exception{when(store.get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,true,1)).thenReturn(new GradeRetractionStore.View(f.f.id,1,value(),true));var r=req("GET",null);r.removeHeader("Origin");assertEquals(200,api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",r).getStatusCode().value());verify(store).get(f.f.group,f.f.space,f.study,f.assignment,f.f.id,f.f.actor,true,1);var query=req("GET",null);query.addParameter("authorId",f.f.actor.toString());status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",query));}
 @Test void strictExactJsonTextAndIntegralVersionsRejectForgedFields(){for(String value:List.of("{}",input()+" {}",input().replace("Grade",""),input().replace("Grade","\\u0000"),input().replace("Grade","\\ud800"),input().replace("Grade","x".repeat(8193)),input().replace("RETRACTED","ACTIVE"),input().replace("RETRACTED",""),input().replace("\"state\":\"RETRACTED\"","\"state\":1"),input().replace("}",",\"reviewerId\":\"spoof\"}"),input().replace("}",",\"reason\":\"Duplicate\"}"))){status(400,()->change(req("PUT",value)));}verifyNoInteractions(store);}
 @Test void requiresStrongGradeVersionAndBoundedExactQuery(){var missing=req("PUT",input());missing.removeHeader("If-Match");status(428,()->change(missing));for(var tag:List.of("*","W/\"gr0\"","\"su1\"","\"gr01\"","\"gr9999999999999999999\"")){var r=req("PUT",input());r.removeHeader("If-Match");r.addHeader("If-Match",tag);status(400,()->change(r));}var duplicate=req("PUT",input());duplicate.addHeader("If-Match","\"gr0\"");status(400,()->change(duplicate));var limit=req("GET",null);limit.addParameter("limit","11");status(400,()->api.history(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",limit));var body=req("GET","{}");status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",body));verifyNoInteractions(store);}
 @Test void malformedCredentialOriginAndRemovedMembershipNeverReachPersistence(){var insecure=req("PUT",input());insecure.setSecure(false);var duplicate=req("PUT",input());duplicate.addHeader("Cookie","__Host-brain_guest="+f.f.token);var cross=req("PUT",input());cross.removeHeader("Origin");cross.addHeader("Origin","https://elsewhere.invalid");for(var r:List.of(insecure,duplicate,cross))assertThrows(ResponseStatusException.class,()->change(r));verifyNoInteractions(store);when(f.f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.f.actor,"REGISTERED",List.of()));status(404,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),"1",req("GET",null)));verifyNoInteractions(store);}
 @Test void validUnicodeByteBoundaryAndBodyLimitAreExplicit(){assertDoesNotThrow(()->GradeRetractionInput.validate(new GradeRetractionInput("RETRACTED","가".repeat(2730)+"ab")));assertThrows(ResponseStatusException.class,()->GradeRetractionInput.validate(new GradeRetractionInput("RETRACTED","가".repeat(2731))));status(413,()->change(req("PUT"," ".repeat(20481))));var type=req("PUT",input());type.setContentType("text/plain");status(415,()->change(type));verifyNoInteractions(store);}
 @Test void canonicalGradeTargetVersionIsRequired(){for(var version:List.of("0","01","-1","1.0","1e3","+1","9223372036854775808"))status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),f.f.id.toString(),version,req("GET",null)));verifyNoInteractions(store);}
}
